inline_styles:
/* SKKNI Hub Styling */
.skkni-hero {
    background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 60%, #0369a1 100%);
    color: #ffffff;
    padding: 60px 0 50px;
    text-align: center;
}
.skkni-hero h1 {
    font-size: clamp(1.8rem, 3.5vw, 2.7rem);
    font-weight: 800;
    margin: 0 0 14px;
    line-height: 1.25;
}
.skkni-hero p {
    font-size: 1.05rem;
    opacity: 0.92;
    max-width: 740px;
    margin: 0 auto 28px;
    line-height: 1.6;
}
.skkni-stats-row {
    display: flex;
    justify-content: center;
    gap: 32px;
    flex-wrap: wrap;
    margin-top: 28px;
}
.skkni-stat-box {
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.22);
    border-radius: 12px;
    padding: 12px 24px;
    min-width: 140px;
    backdrop-filter: blur(4px);
}
.skkni-stat-box strong {
    display: block;
    font-size: 1.8rem;
    font-weight: 800;
    color: #38bdf8;
}
.skkni-stat-box span {
    font-size: 0.85rem;
    opacity: 0.95;
}

/* Search bar */
.skkni-search-form {
    background: #ffffff;
    border-radius: 12px;
    padding: 6px;
    display: flex;
    gap: 8px;
    max-width: 660px;
    margin: 0 auto;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
}
.skkni-search-form input {
    flex: 1;
    border: none;
    outline: none;
    padding: 12px 18px;
    font-size: 1rem;
    color: #1f2937;
    background: transparent;
}
.skkni-search-form button {
    background: var(--orange, #f97316);
    color: #ffffff;
    border: none;
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 700;
    cursor: pointer;
    transition: background 0.2s;
}
.skkni-search-form button:hover {
    background: #ea580c;
}

/* Filter Section */
.skkni-filter-bar {
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    padding: 18px 0;
}
.skkni-filter-label {
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #64748b;
    margin-bottom: 8px;
    letter-spacing: 0.05em;
}
.skkni-chip-row {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    align-items: center;
}
.skkni-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 14px;
    border-radius: 999px;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    color: #334155;
    font-size: 0.85rem;
    font-weight: 500;
    text-decoration: none;
    transition: all 0.2s ease;
}
.skkni-chip:hover {
    border-color: #1e40af;
    color: #1e40af;
}
.skkni-chip.active {
    background: #1e40af;
    color: #ffffff;
    border-color: #1e40af;
    font-weight: 600;
}

/* Card Grid */
.skkni-main-content {
    padding: 48px 0 64px;
}
.skkni-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 24px;
}
.skkni-card {
    background: #ffffff;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.skkni-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.09);
    border-color: #cbd5e1;
}
.skkni-card-header {
    padding: 16px 20px;
    border-bottom: 1px solid #f1f5f9;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fafafa;
}
.skkni-badge-sector {
    display: inline-block;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 4px 10px;
    border-radius: 6px;
    letter-spacing: 0.04em;
    background: #e0f2fe;
    color: #0369a1;
}
.skkni-badge-kkni {
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    background: #f1f5f9;
    padding: 3px 8px;
    border-radius: 4px;
}
.skkni-card-body {
    padding: 20px;
    flex: 1;
    display: flex;
    flex-direction: column;
}
.skkni-card-ref {
    font-size: 0.8rem;
    font-weight: 600;
    color: #0284c7;
    margin-bottom: 6px;
}
.skkni-card-title {
    font-size: 1.15rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.35;
    margin: 0 0 10px;
}
.skkni-card-title a {
    color: inherit;
    text-decoration: none;
}
.skkni-card-title a:hover {
    color: #1e40af;
}
.skkni-card-desc {
    font-size: 0.88rem;
    color: #475569;
    line-height: 1.55;
    margin: 0 0 18px;
    flex: 1;
}
.skkni-card-meta {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 0.8rem;
    color: #64748b;
    border-top: 1px solid #f1f5f9;
    padding-top: 14px;
    margin-top: auto;
}
.skkni-card-meta span {
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
.skkni-card-footer {
    padding: 14px 20px;
    background: #f8fafc;
    border-top: 1px solid #f1f5f9;
}
.skkni-btn-detail {
    display: block;
    text-align: center;
    background: #1e40af;
    color: #ffffff;
    padding: 9px 16px;
    border-radius: 8px;
    font-size: 0.88rem;
    font-weight: 600;
    text-decoration: none;
    transition: background 0.2s;
}
.skkni-btn-detail:hover {
    background: #1d4ed8;
}

/* Featured Training Showcase */
.skkni-showcase {
    background: #f0fdf4;
    border-top: 1px solid #bbf7d0;
    border-bottom: 1px solid #bbf7d0;
    padding: 60px 0;
}
.skkni-showcase-title {
    font-size: clamp(1.5rem, 3vw, 2rem);
    font-weight: 800;
    color: #14532d;
    text-align: center;
    margin: 0 0 12px;
}
.skkni-showcase-sub {
    font-size: 1rem;
    color: #166534;
    text-align: center;
    max-width: 720px;
    margin: 0 auto 36px;
    line-height: 1.6;
}
.ft-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 24px;
}
.ft-card {
    background: #ffffff;
    border-radius: 12px;
    border: 1px solid #dcfce7;
    box-shadow: 0 4px 12px rgba(22, 101, 52, 0.06);
    padding: 24px;
    display: flex;
    flex-direction: column;
    transition: transform 0.2s;
}
.ft-card:hover {
    transform: translateY(-3px);
}
.ft-badge {
    align-self: flex-start;
    background: #dcfce7;
    color: #15803d;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 3px 8px;
    border-radius: 4px;
    margin-bottom: 12px;
}
.ft-title {
    font-size: 1.12rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 8px;
    line-height: 1.35;
}
.ft-desc {
    font-size: 0.88rem;
    color: #475569;
    line-height: 1.5;
    margin: 0 0 16px;
    flex: 1;
}
.ft-btn {
    display: inline-block;
    background: #16a34a;
    color: #ffffff;
    text-align: center;
    padding: 10px 16px;
    border-radius: 8px;
    font-size: 0.88rem;
    font-weight: 600;
    text-decoration: none;
    transition: background 0.2s;
}
.ft-btn:hover {
    background: #15803d;
}
